from pathlib import Path
import json,re
w=Path(__file__).parent
ledger=[json.loads(s) for s in (w/'source-ledger.jsonl').read_text().splitlines()]
by={}
for s in ledger:
 m=re.match(r'\[([A-Z]+\d+)\]',s['quote'])
 if m: by[m[1]]=s
 if s['anchor'].endswith('reviewed-0001'): by['T'+s['anchor'][11:13]]=s
# Resolve visual source pages explicitly; raw page 5 retains uncertainty.
for n in range(1,6):
 anchor=f'pdf-page-{n:04d}'+('-reviewed-0001' if n<5 else '')
 by[f'T0{n}']=next(s for s in ledger if s['anchor']==anchor)
reports={s['anchor']:s for s in ledger if s['path']=='input/report.md' and s['anchor'].startswith('C08-ERR-')}
rows=[
('supported','sufficient','proved',['T01','R01','J01'],'Does accepted receipt IN-A comprise exactly 96 individual A units?',['Eight full crates were actually accepted; R01 assigns twelve units per full crate.','Eight times twelve is 96, with no partial-container exception.'],'Accept 96 inbound A units; do not confuse this movement quantity with closing stock.','Audit.inboundA = 96'),
('refuted','invalid_inference','refuted',['T02','R01','J01'],'Does IN-B contain 24 units, and are cartons equivalent to crates?',['The signed accepted receipt is two full cartons, not crates.','R01 assigns six units per carton and twelve per crate. Thus B inbound is 12, not 24; the claimed conversion uses the wrong container.'],'Correct B inbound to 12 units and preserve the six-unit carton factor.','Audit.inboundB ≠ 24'),
('refuted','invalid_inference','refuted',['J01','J02','R01','R02','R04','K03','T03'],'Is A book on-hand 136 units at the stated cutoff?',['Start with 100; add 96 accepted inbound; subtract 60 actual outbound; add 12 accepted return.','The returned crate is inside the fenced cage boundary. Complete A movements give 148; 136 omits the separately accepted return.'],'Correct book A on-hand to 148; retain the departure and its separate return.','Audit.bookA ≠ 136'),
('refuted','invalid_inference','refuted',['R02','R03','J01','J02','K03','BIN02'],'Does physical presence make A available stock equal its 148-unit book balance?',['A book on-hand is 148 after all complete movements.','Seven quarantined A units stay on site but R03 excludes them from availability; BIN02 records no release. Availability is 148 minus 7 = 141.'],'Report 141 available A units while keeping book on-hand 148.','Audit.availableA ≠ 148'),
('refuted','invalid_inference','refuted',['J01','J03','R01','R02','K03','T04'],'Did all three requested B cartons ship, leaving book on-hand 34?',['Only two full cartons crossed the signed actual handoff; the third remained on the shelf and was canceled.','Book B is 40 + 12 - 12 = 40. Subtracting requested rather than actual cartons produces the erroneous 34.'],'Report 40 book B units; only two cartons shipped.','Audit.bookB ≠ 34 ∧ Audit.deliveredB ≠ Audit.requestedB'),
('supported','sufficient','proved',['R03','J01','J03','K03','BIN03'],'Is B available stock 32 units after its separate reservation?',['Complete B movements give 40 book on-hand.','The separate eight B units are still reserved at cutoff, so availability is 40 minus 8 = 32. A quarantine does not enter this calculation.'],'Retain 32 available B units, distinct from physical/book 40.','Audit.availableB = 32'),
('refuted','invalid_inference','refuted',['T03','J02','M02','R01','R02'],'Were all sixty dispatched A units delivered to the customer?',['Five crates departed, but the customer accepted only four and refused the fifth.','Four crates are 48 delivered units; the twelve-unit fifth crate returned. Traced custody does not mean full customer delivery.'],'Report 60 dispatched, 48 delivered and 12 returned A units.','Audit.deliveredA ≠ Audit.dispatchedA'),
('refuted','invalid_inference','refuted',['T04','J03','M03','R01','R02'],'Was the original three-carton B customer order completely delivered?',['M03 confirms delivery of the two actual handed-over cartons only.','The third requested carton was canceled without leaving. Two delivered cartons do not fulfill the original three-carton denominator.'],'State that all actually shipped B cartons arrived, while the original order was not fully delivered.','Audit.deliveredB ≠ Audit.requestedB'),
('both','disputed','blocked',['N01','N02','N03','N04','R04','BIN04'],'Can the true physical A count at the common cutoff and boundary be fixed at exactly 148?',['Elin records 148 while Tomas records 147 for the identical lot, cutoff and included quarantine/cage.','Both have equal authority and neither is canceled. Agreement of the book calculation with one count does not adjudicate the other.'],'Obtain a signed recount or authorized reconciliation; report both observations meanwhile.',None),
('undetermined','insufficient_support','blocked',['J04','BIN04','R03'],'Does a minus-one C journal balance establish exactly one physically missing unit?',['The signed-integer ledger is 0 - 9 + 8 = -1.','J04 expressly lacks a physical count and approved import correction. A possible unit-mapping error is unresolved. The missing bridge from book anomaly to physical shortage prevents either a one-unit shortage finding or its negation.'],'Report the -1 book anomaly; request the unit mapping, approved correction and physical reconciliation.',None),
('undetermined','insufficient_support','blocked',['T05','M01','M04','R04','K04','BIN05'],'Does the pale D field conclusively establish that exactly 78 units were accepted?',['All five original raster pages were inspected. The pale final line on page 5 visually appears to read 78, but OCR omitted it; the receiver acceptance box is blank.','M01 provides provisional unsigned 74 and 78 suggestions, no signed correction or authenticated reconciliation. Even perfect legibility of a planned field would not establish actual accepted quantity.','No unique accepted D quantity is established, and the absence of acceptance evidence does not prove the shipment failed.'],'Request authenticated acceptance/correction and the missing recount attachment; keep accepted quantity undetermined.',None),
('refuted','invalid_inference','refuted',['K03','J04','N02','BIN04'],'Was every warehouse lot reconciled at cutoff, including C and the unresolved A count?',['J04 explicitly states C physical reconciliation is incomplete; BIN04 records its unresolved exception.','C belongs to the named lot domain and is a direct counterexample to every-lot reconciliation. The unresolved A count independently defeats blanket closure.'],'Withdraw the universal statement and list unresolved A, C and D questions separately.','∀ (reconciled : Audit.Lot → Prop), ¬ reconciled Audit.Lot.c → ¬ (∀ lot, reconciled lot)'),
('refuted','invalid_inference','refuted',['R03','J03','BIN02','BIN03'],'Does subtracting A quarantine from B book stock yield B availability?',['Lots are distinct; A holds seven quarantined units and B separately reserves eight different units.','B availability is 40 - 8 = 32. The proposed cross-lot subtraction 40 - 7 = 33 differs, and violates the lot-identity rule.'],'Deduct B\'s own eight reserved units; keep A quarantine assigned to A.','Audit.bookB - 7 ≠ Audit.availableB'),
('not_applicable','nonformal','not_attempted',['K01','R02'],'Is there a supplied operational definition that can decide whether the return workflow is elegantly designed?',['K01 assigns custody roles and R02 defines movement semantics.','Neither provides a criterion for elegance. Operational correctness or traceability does not mathematically establish an aesthetic judgment.'],'Label elegance as an opinion or supply an agreed assessment criterion.',None)]
findings=[]
for i,(state,arg,formal,keys,q,reason,rec,target) in enumerate(rows,1):
 cid=f'C08-ERR-{i:02d}'; src=reports[cid]
 evidence=[]
 for key in keys:
  s=by[key]; evidence.append({'path':s['path'],'anchor':s['anchor'],'quote':s['quote'],'original_path':next(d['external'] for d in json.loads((w/'ingestion.json').read_text())['documents'] if d['id']==s['document_id']),'semantic_marker':key})
 findings.append({'claim_id':cid,'report_quote':src['quote'].split('\n\nCitations:')[0],'report_anchor':cid,'parent_finding':cid,'atomic_target':q,'question':q,'evidence':evidence,'rules':['Use R01 exact full-container conversion, R02 actual custody movements and R03 same-lot availability where applicable.','R04/K03 completeness covers A/B movements for the stated day only; equal-authority counts remain conflicting and missing D/C evidence is not negative fact.'] if i!=14 else ['No source defines an objective criterion for elegance.'],'assumptions':['The synthetic source authority and finite warehouse boundary are accepted as stated; no source authenticity outside the fixture is certified.'],'reasoning':[f'{j}. {s}' for j,s in enumerate(reason,1)],'semantic_state':state,'argument_status':arg,'formal_status':formal,'proofs':[] if target is None else [{'module':'Audit','theorem':f'Audit.claim{i:02d}','relation':'supports' if state=='supported' else 'refutes','target':target}],'limits':['Results concern the specified lots, warehouse boundary and 18:00 cutoff on 14 April 2032. Book arithmetic does not select the true physical A count or resolve D acceptance.','Native pages 1–4 were visually checked and corrected through retained manual transcriptions; page 5 retains quantity/acceptance uncertainty.' if i in [1,2,3,5,7,8,11] else 'Formal checks prove encoded targets only; unsupported physical facts are not inferred from missing evidence.'],'recommendation':rec})
(w/'findings.json').write_text(json.dumps(findings,indent=2,ensure_ascii=False)+'\n')
(w/'claims.json').write_text(json.dumps({'claims':[{'claim_id':f['claim_id'],'report_anchor':f['report_anchor'],'exact_claim':f['report_quote'],'atomic_target':f['atomic_target'],'coverage':'assessed'} for f in findings],'excluded_claims':[]},indent=2)+'\n')
(w/'coverage-acknowledgement.json').write_text(json.dumps({'documents':[{'document_id':'D00008','reason':'Original five pages visually inspected; pages 1–4 corrected and accepted with hash-bound manual transcriptions. Page 5 pale field not recovered reliably by OCR; accepted quantity also lacks receiver signature.','impact':'All fourteen report findings assessed. C08-ERR-11 remains undetermined, without direct formal claim. Other direct targets use visually checked pages 1–4 and/or independent complete text records. Raw OCR and original bytes remain intact.'}]},indent=2)+'\n')
